          "es": "La nueva prensa térmica Beinsen Gante te lo pone fácil durante todo el proceso de personalización. Comienza regulando la presión necesaria con su nuevo mando regulador mejorado, utiliza el controlador digital para seleccionar tiempo y temperatura y al acabar separa la placa calefactora de manera sencilla y elegante con el resorte de gas.",
          "en": "The new Beinsen Gante makes the full personalization process easier. Start by adjusting pressure with its improved regulator, use the digital controller to set time and temperature, and finish by separating the heating plate smoothly with the gas spring.",
          "pt": "A nova prensa térmica Beinsen Gante torna-lhe fácil todo o processo de personalização. Comece a regular a pressão necessária com o seu novo manípulo regulador melhorado, utilize o controlador digital para selecionar tempo e temperatura e, ao terminar, separe a placa de aquecimento de forma simples e elegante com a mola a gás.",
          "it": "La nuova pressa termica Beinsen Gante ti semplifica l'intero processo di personalizzazione. Inizia regolando la pressione necessaria con la sua nuova manopola di regolazione migliorata, utilizza il controller digitale per selezionare tempo e temperatura e al termine separa la piastra riscaldante in modo semplice ed elegante con la molla a gas."
