          "en": "Everything designed for your comfort. Use the sliding lower tray to place garments easily with plenty of maneuvering space — then no levers, just press the side buttons and let the Beinsen Alaska do its job. Like having a pneumatic press but without the compressor.",
          "pt": "Tudo pensado para o seu conforto. Aproveite o tabuleiro inferior deslizante para colocar a peça com facilidade graças ao grande espaço de manobra e depois… nada de alavancas… pressione os botões laterais e a sua nova Beinsen Alaska fará o seu trabalho. Como ter uma prensa pneumática mas sem compressor.",
          "it": "Tutto pensato per la sua comodità. Sfrutti il vassoio inferiore scorrevole per posizionare il capo con facilità grazie all'ampio spazio di manovra e poi… niente leve… prema i pulsanti laterali e la sua nuova Beinsen Alaska farà il suo lavoro. Come avere una pressa pneumatica ma senza compressore."
